    # v2.21: sticky figure toggle, one-open-at-a-time sidebar sections, the "Jump to" menu, the quick-edit strip
    tags$script(HTML(
      "(function() {
         function sections() { return document.querySelectorAll('details.kc-section'); }
         function closeOthers(keep) { sections().forEach(function(o) { if (o !== keep && o.open) o.open = false; }); }
         // accordion: opening a section closes the others (the toggle event fires after the native state change,
         // so the keyboard (Enter / Space on a summary) and the mouse behave the same)
         document.addEventListener('toggle', function(ev) {
           var d = ev.target;
           if (d && d.tagName === 'DETAILS' && d.classList.contains('kc-section') && d.open) {
             closeOthers(d);
             window.requestAnimationFrame(function() { d.scrollIntoView({block: 'nearest'}); });
           }
         }, true);
         // jump menu: open the section, scroll it to the top of the window, move focus to its summary
         document.addEventListener('change', function(ev) {
           var t = ev.target;
           if (!t || t.id !== 'sidebar_jump') return;
           var d = t.value ? document.getElementById('sec_' + t.value) : null;
           if (d) {
             closeOthers(d); d.open = true;
             window.requestAnimationFrame(function() {
               d.scrollIntoView({block: 'start'});
               var s = d.querySelector('summary'); if (s && s.focus) s.focus({preventScroll: true});
             });
           }
           t.value = '';
         });
         document.addEventListener('click', function(ev) {
           var t = ev.target && ev.target.closest ? ev.target.closest('button.kc-collapse-all, button.kc-qe-toggle') : null;
           if (!t) return;
           if (t.classList.contains('kc-collapse-all')) { sections().forEach(function(o) { o.open = false; }); }
           else { var cb = document.getElementById('quick_edit_open'); if (cb) cb.click(); }
         });
         // checkbox sticky_figure / quick_edit_open: pure client side, no round trip
         function qeLabel(on) { var b = document.getElementById('kc_qe_toggle'); if (b) b.textContent = on ? 'Hide quick edit' : 'Show quick edit'; }
         if (window.jQuery) jQuery(document).on('shiny:inputchanged', function(ev) {
           if (ev.name === 'sticky_figure') {
             var m = document.getElementById('main_panel');
             if (m) m.classList.toggle('kc-sticky', !!ev.value);
             if (window.kcReportSize) window.kcReportSize();
           }
           else if (ev.name === 'quick_edit_open') qeLabel(!!ev.value);
         });
         // colour pickers of the strip: an <input type=color> reports to Shiny (debounced) only when the user picks
         var timers = {};
         document.addEventListener('input', function(ev) {
           var t = ev.target;
           if (!t || !t.classList || !t.classList.contains('kc-qe-color')) return;
           var sw = document.getElementById(t.id.replace('qe_color_', 'qe_swatch_')); if (sw) sw.style.backgroundColor = t.value;
           clearTimeout(timers[t.id]);
           timers[t.id] = setTimeout(function() {
             if (window.Shiny && Shiny.setInputValue) Shiny.setInputValue(t.id, t.value, {priority: 'event'});
           }, 150);
         });
         // a user click on a show box adds / removes the sample (programmatic updates are not trusted events)
         document.addEventListener('change', function(ev) {
           var t = ev.target;
           if (!ev.isTrusted || !t || t.type !== 'checkbox' || !t.closest || !t.closest('.kc-qe-show')) return;
           var row = t.closest('.kc-qe-row');
           if (row && window.Shiny && Shiny.setInputValue)
             Shiny.setInputValue('qe_show_event', {sample: row.getAttribute('data-sample'), show: t.checked}, {priority: 'event'});
         });
         // the server tells the strip the colour each sample really has (sidebar colour, palette or the strip's own)
         function swatches(m) {
           for (var i = 0; i < m.ids.length; i++) {
             var inp = document.getElementById(m.ids[i]), c = m.colors[i];
             if (inp && document.activeElement !== inp && inp.value.toLowerCase() !== String(c).toLowerCase()) inp.value = c;
             var sw = document.getElementById(m.ids[i].replace('qe_color_', 'qe_swatch_')); if (sw) sw.style.backgroundColor = c;
           }
         }
         if (window.Shiny && Shiny.addCustomMessageHandler) Shiny.addCustomMessageHandler('kcSwatches', swatches);
         else if (window.jQuery) jQuery(document).on('shiny:connected', function() { Shiny.addCustomMessageHandler('kcSwatches', swatches); });
         // v2.22: click-to-edit labels on the figure (the inline SVG of output od_plot_svg). mark() tags the legend
         // entries, axis titles and title / subtitle; a click opens one popover whose Apply writes into the existing
         // quick-edit / sidebar inputs, so the v2.21 pipeline does the rest. Event-delegated; nothing is kept
         // across re-renders except the popover itself.
         var kcCur = null, kcPop = null;
         function kcVal(id) { var e = document.getElementById(id); return e ? e.value : ''; }
         function kcSamples() {
           var out = [];
           document.querySelectorAll('.kc-qe-row').forEach(function(row) {
             var inp = row.querySelector('input[id^=qe_name_]'); if (!inp) return;
             out.push({name: (inp.value || inp.placeholder || '').trim(), id: inp.id.replace('qe_name_', ''), sample: row.getAttribute('data-sample')});
           });
           return out;
         }
         function kcMark() {
           var host = document.getElementById('od_plot_svg'); if (!host) return;
           var ss = kcSamples(), g = {x_axis_label: kcVal('x_axis_label').trim(), plot_title: kcVal('plot_title').trim(),
                                      plot_subtitle: kcVal('plot_subtitle').trim()};
           host.querySelectorAll('svg text').forEach(function(t) {
             var s = (t.textContent || '').trim(), kind = null, id = null, i;
             if (/rotate\\(-90/.test(t.getAttribute('transform') || '')) kind = 'y_axis_label';
             else if (s) {
               for (i = 0; i < ss.length; i++) if (ss[i].name === s) { kind = 'sample'; id = ss[i].id; break; }
               if (!kind) for (var k in g) if (g[k] && g[k] === s) { kind = k; break; }
             }
             if (!kind) return;
             t.setAttribute('data-kc', kind);
             if (id) t.setAttribute('data-kc-id', id);
             t.classList.add('kc-ed');
             t.setAttribute('aria-label', 'Click to edit ' + (kind === 'sample' ? s : kind.replace(/_/g, ' ')));
           });
         }
         function kcSetText(id, v) {
           var e = document.getElementById(id); if (!e) return;
           if (window.jQuery) jQuery(e).val(v).trigger('input');
           else { e.value = v; e.dispatchEvent(new Event('input', {bubbles: true})); }
         }
         function kcClose() { if (kcPop) kcPop.style.display = 'none'; kcCur = null; }
         function kcPlace(t) {
           var op = kcPop.offsetParent || document.body, or = op.getBoundingClientRect(), r = t.getBoundingClientRect();
           var left = r.left - or.left + (op.scrollLeft || 0), top = r.bottom - or.top + (op.scrollTop || 0) + 4;
           var maxL = Math.max(0, op.clientWidth - kcPop.offsetWidth - 4);
           if (top + kcPop.offsetHeight > (op.scrollHeight || 1e9) && r.top - or.top - kcPop.offsetHeight - 4 >= 0)
             top = r.top - or.top + (op.scrollTop || 0) - kcPop.offsetHeight - 4;
           kcPop.style.left = Math.max(0, Math.min(left, maxL)) + 'px';
           kcPop.style.top = Math.max(0, top) + 'px';
         }
         function kcApply() {
           if (!kcCur || !kcPop) return;
           var txt = kcPop.querySelector('input[type=text]'), v = txt ? txt.value : '';
           if (kcCur.kind === 'sample') {
             kcSetText('qe_name_' + kcCur.id, v);
             var shw = kcPop.querySelector('input[type=checkbox]');
             if (shw && !shw.checked) {
               var cb = document.getElementById('qe_show_' + kcCur.id); if (cb) cb.checked = false;
               if (window.Shiny && Shiny.setInputValue) Shiny.setInputValue('qe_show_event', {sample: kcCur.sample, show: false}, {priority: 'event'});
             }
           } else kcSetText(kcCur.kind, v);
           kcClose();
         }
         function kcMk(tag, props) { var e = document.createElement(tag); for (var k in props) e[k] = props[k]; return e; }
         function kcOpen(t) {
           var kind = t.getAttribute('data-kc'), id = t.getAttribute('data-kc-id'), host = document.getElementById('main_panel');
           if (!host) return;
           if (!kcPop) {
             kcPop = kcMk('div', {id: 'kc_canvas_pop'}); kcPop.setAttribute('role', 'dialog'); host.appendChild(kcPop);
           } else if (kcPop.parentNode !== host) host.appendChild(kcPop);
           kcCur = {kind: kind, id: id, sample: null};
           while (kcPop.firstChild) kcPop.removeChild(kcPop.firstChild);
           var txt = kcMk('input', {type: 'text', className: 'kc-pop-text'}), cur = '';
           if (kind === 'sample') {
             var ni = document.getElementById('qe_name_' + id); if (!ni) return;
             var row = ni.closest('.kc-qe-row'); kcCur.sample = row ? row.getAttribute('data-sample') : null;
             cur = ni.value || ni.placeholder || '';
           } else cur = kcVal(kind);
           txt.value = cur; txt.setAttribute('aria-label', 'New text');
           txt.addEventListener('keydown', function(ev) { if (ev.key === 'Enter') { kcApply(); } });
           kcPop.appendChild(txt);
           if (kind === 'sample') {
             var ci = document.getElementById('qe_color_' + id);
             var col = kcMk('input', {type: 'color', value: ci ? ci.value : '#000000'});
             col.setAttribute('aria-label', 'Colour');
             col.addEventListener('input', function() {   // applied at once, through the strip's own picker
               var c = document.getElementById('qe_color_' + id);
               if (c) { c.value = col.value; c.dispatchEvent(new Event('input', {bubbles: true})); }
             });
             var lab = kcMk('label', {}), shw = kcMk('input', {type: 'checkbox', checked: true});
             lab.appendChild(shw); lab.appendChild(document.createTextNode(' show'));
             kcPop.appendChild(col); kcPop.appendChild(lab);
           }
           var btns = kcMk('div', {className: 'kc-pop-btns'});
           var ap = kcMk('button', {type: 'button', className: 'btn btn-primary btn-xs', textContent: 'Apply'});
           var cl = kcMk('button', {type: 'button', className: 'btn btn-default btn-xs', textContent: 'Close'});
           ap.addEventListener('click', kcApply); cl.addEventListener('click', kcClose);
           btns.appendChild(ap); btns.appendChild(cl); kcPop.appendChild(btns);
           kcPop.style.display = 'block'; kcPlace(t);
           txt.focus(); txt.select();
         }
         document.addEventListener('click', function(ev) {
           var t = ev.target && ev.target.closest ? ev.target.closest('#od_plot_svg text.kc-ed') : null;
           if (t) { kcOpen(t); return; }
           if (kcPop && kcPop.style.display !== 'none' && !kcPop.contains(ev.target)) kcClose();
         });
         document.addEventListener('keydown', function(ev) { if (ev.key === 'Escape' && kcCur) kcClose(); });
         // after the SVG is replaced: tag its labels again; the popover stays only while its label still exists
         function kcAfterRender() {
           kcMark();
           if (!kcCur || !kcPop) return;
           var hit = null;
           document.querySelectorAll('#od_plot_svg text.kc-ed').forEach(function(t) {
             if (!hit && t.getAttribute('data-kc') === kcCur.kind && (kcCur.kind !== 'sample' || t.getAttribute('data-kc-id') === kcCur.id)) hit = t;
           });
           if (hit) kcPlace(hit); else kcClose();
         }
         if (window.jQuery) {
           jQuery(document).on('shiny:value', function(ev) {
             if (ev.name === 'od_plot_svg' || ev.name === 'quick_edit_rows') window.requestAnimationFrame(kcAfterRender);
           });
           jQuery(document).on('shiny:idle', kcMark);
           jQuery(document).on('shiny:inputchanged', function(ev) { if (ev.name === 'canvas_edit' && !ev.value) kcClose(); });
         }
       })();"
    )),
    # v2.23.2: Copy figure -- the preview (inline SVG or PNG) is drawn to a PNG in the browser and put on the clipboard
    tags$script(HTML(
      "(function() {
         var SEL = {main: ['#od_plot_svg svg', '#od_plot_img img', '#od_plot img'], analysis: ['#analysis_img img', '#analysis_plot img'],
                    fit: ['#fit_img img', '#fit_plot img'], compose: ['#compose_img img', '#compose_plot img'],
                    compare: ['#compare_img img', '#compare_plot img'], legend_key: ['#legend_key_preview img']};
         var BOX = {main: '#od_plot_svg, #od_plot_img, #od_plot', analysis: '#analysis_img, #analysis_plot', fit: '#fit_img, #fit_plot',
                    compose: '#compose_img, #compose_plot', compare: '#compare_img, #compare_plot', legend_key: '#legend_key_preview'};
         function figEl(kind) {
           var l = SEL[kind] || [];
           for (var i = 0; i < l.length; i++) { var e = document.querySelector(l[i]); if (e) return e; }
           return null;
         }
         function report(kind, ok, w, h, why) {
           if (window.Shiny && Shiny.setInputValue)
             Shiny.setInputValue('kc_copy_result', ok ? {kind: kind, ok: true, w: w, h: h} : {kind: kind, ok: false, reason: why}, {priority: 'event'});
         }
         function toPng(el, dims) {
           return new Promise(function(resolve, reject) {
             var isSvg = el.tagName.toLowerCase() === 'svg', cw, ch, scale, src, revoke = null, img;
             function draw(source) {
               var c = document.createElement('canvas'); c.width = Math.max(1, Math.round(cw * scale)); c.height = Math.max(1, Math.round(ch * scale));
               var g = c.getContext('2d'); g.fillStyle = '#ffffff'; g.fillRect(0, 0, c.width, c.height);
               g.drawImage(source, 0, 0, c.width, c.height);
               dims.w = c.width; dims.h = c.height;
               c.toBlob(function(b) { if (b) resolve(b); else reject(new Error('the browser could not make a PNG')); }, 'image/png');
             }
             if (isSvg) {
               var r = el.getBoundingClientRect(); cw = r.width; ch = r.height;
               if (!(cw > 0 && ch > 0)) { reject(new Error('the figure has no size on the page')); return; }
               scale = Math.min((window.devicePixelRatio || 1) * 3, 4000 / Math.max(cw, ch));
               var cl = el.cloneNode(true);
               cl.setAttribute('width', Math.round(cw * scale)); cl.setAttribute('height', Math.round(ch * scale));
               if (!cl.getAttribute('xmlns')) cl.setAttribute('xmlns', 'http://www.w3.org/2000/svg');
               var url = URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(cl)], {type: 'image/svg+xml;charset=utf-8'}));
               img = new Image();
               img.onload = function() { try { draw(img); } catch (e) { reject(e); } URL.revokeObjectURL(url); };
               img.onerror = function() { URL.revokeObjectURL(url); reject(new Error('the figure could not be drawn')); };
               img.src = url;
             } else {
               if (!el.complete || !(el.naturalWidth > 0)) { reject(new Error('the figure is still loading')); return; }
               cw = el.naturalWidth; ch = el.naturalHeight; scale = Math.min(3, 4000 / Math.max(cw, ch));
               try { draw(el); } catch (e) { reject(e); }
             }
           });
         }
         function why(e) {
           if (e && e.name === 'NotAllowedError') return 'the browser refused clipboard access';
           var m = e && (e.message || e.name); return m ? String(m).slice(0, 100) : 'unknown error';
         }
         window.kcCopyFigure = function(kind) {
           var el = figEl(kind);
           if (!el) { report(kind, false, 0, 0, 'no figure on the page'); return; }
           if (!navigator.clipboard || !navigator.clipboard.write || !window.ClipboardItem) {
             report(kind, false, 0, 0, 'this browser or page (needs https or localhost) has no clipboard image support'); return;
           }
           var dims = {w: 0, h: 0}, done, p;
           try { p = toPng(el, dims); } catch (e) { report(kind, false, 0, 0, why(e)); return; }
           p.catch(function() {});
           try { done = navigator.clipboard.write([new ClipboardItem({'image/png': p})]); }
           catch (e) { done = p.then(function(b) { return navigator.clipboard.write([new ClipboardItem({'image/png': b})]); }); }
           done.then(function() { report(kind, true, dims.w, dims.h); }, function(e) { report(kind, false, 0, 0, why(e)); });
         };
         var hov = null;
         document.addEventListener('mouseover', function(ev) {
           hov = null; if (!ev.target || !ev.target.closest) return;
           for (var k in BOX) { if (ev.target.closest(BOX[k])) { hov = k; break; } }
         });
         document.addEventListener('keydown', function(ev) {
           if (!hov || ev.altKey || ev.shiftKey || !(ev.metaKey || ev.ctrlKey) || String(ev.key).toLowerCase() !== 'c') return;
           var a = document.activeElement, sel = window.getSelection ? String(window.getSelection()) : '';
           if (sel || (a && /^(input|textarea|select)$/i.test(a.tagName))) return;
